import { useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useNavigate } from 'react-router-dom'
import { api } from '@/lib/api'
import { Settings as SettingsIcon, Server, Key, Info, Bot, Shield, Trash2, CheckCircle, AlertCircle, ArrowRight, Wrench } from 'lucide-react'

// 统一工具视图（/api/v1/tools/{key} 返回结构的关键字段）
interface ToolView {
  key: string
  name: string
  status: string
  enabled: boolean
  healthy: boolean
  version?: string | null
  provider_registered?: boolean
  installing?: boolean
  problem?: string | null
}

interface InfoRow {
  label: string
  value: string
}

const TOOL_STATUS_LABEL: Record<string, string> = {
  installed: '已安装',
  not_installed: '未安装',
  installing: '安装中',
  failed: '安装失败',
  uninstalled: '已卸载',
}

const TOOL_STATUS_CLASS: Record<string, string> = {
  installed: 'bg-green-100 text-green-700',
  not_installed: 'bg-gray-100 text-gray-500',
  installing: 'bg-blue-100 text-blue-700',
  failed: 'bg-red-100 text-red-700',
  uninstalled: 'bg-gray-100 text-gray-500',
}

async function fetchToolView(key: string): Promise<ToolView | null> {
  try {
    const res = await fetch(`/api/v1/tools/${key}`)
    if (!res.ok) return null
    const data = await res.json()
    if (!data || data.error) return null
    return data as ToolView
  } catch {
    return null
  }
}

/** CLI Agent 工具卡片：安装状态 + 启用开关 + 健康指示，数据源为 /tools/{key}。 */
function AgentToolCard({ title, toolKey, infoRows }: {
  title: string
  toolKey: string
  infoRows: InfoRow[]
}) {
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  const { data: tool } = useQuery({
    queryKey: ['tool', toolKey],
    queryFn: () => fetchToolView(toolKey),
  })
  const [toggling, setToggling] = useState(false)

  const toggleEnabled = async () => {
    if (!tool) return
    setToggling(true)
    try {
      const action = tool.enabled ? 'disable' : 'enable'
      await fetch(`/api/v1/tools/${toolKey}/${action}`, { method: 'POST' })
      queryClient.invalidateQueries({ queryKey: ['tool', toolKey] })
      queryClient.invalidateQueries({ queryKey: ['status'] })
    } finally {
      setToggling(false)
    }
  }

  const statusLabel = tool ? (TOOL_STATUS_LABEL[tool.status] || tool.status) : '加载中'
  const statusClass = tool ? (TOOL_STATUS_CLASS[tool.status] || 'bg-gray-100 text-gray-500') : 'bg-gray-100 text-gray-500'
  const healthy = tool?.healthy ?? false

  return (
    <div className="rounded-xl border bg-card p-4">
      <div className="mb-3 flex items-center justify-between">
        <h3 className="font-medium flex items-center gap-2">
          <Bot className="h-4 w-4 text-primary" /> {title}
          {/* 健康指示点 */}
          <span
            className={`ml-1 h-2 w-2 rounded-full ${healthy ? 'bg-green-500' : 'bg-gray-300'}`}
            title={healthy ? '健康' : '不可用'}
          />
        </h3>
        <button
          onClick={() => navigate('/tools')}
          className="inline-flex items-center gap-1 rounded-lg border px-2.5 py-1 text-xs text-muted-foreground hover:bg-muted hover:text-foreground"
        >
          <Wrench className="h-3.5 w-3.5" />
          管理工具
        </button>
      </div>

      <div className="grid gap-3 sm:grid-cols-2">
        <div className="rounded-lg bg-muted p-3">
          <p className="text-xs text-muted-foreground">安装状态</p>
          <p className="mt-1">
            <span className={`inline-flex items-center rounded-md px-2 py-0.5 text-xs font-medium ${statusClass}`}>
              {statusLabel}
            </span>
            {tool?.version ? (
              <span className="ml-2 font-mono text-xs text-muted-foreground">{tool.version}</span>
            ) : null}
          </p>
        </div>
        <div className="rounded-lg bg-muted p-3">
          <p className="text-xs text-muted-foreground">启用开关</p>
          <div className="mt-1 flex items-center gap-2">
            <button
              role="switch"
              aria-checked={!!tool?.enabled}
              disabled={!tool || toggling}
              onClick={toggleEnabled}
              className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors disabled:opacity-50 ${
                tool?.enabled ? 'bg-green-500' : 'bg-gray-300'
              }`}
            >
              <span
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  tool?.enabled ? 'translate-x-4' : 'translate-x-0.5'
                }`}
              />
            </button>
            <span className="text-sm text-muted-foreground">
              {toggling ? '处理中...' : tool?.enabled ? '已启用' : '已禁用'}
            </span>
          </div>
        </div>
        <div className="rounded-lg bg-muted p-3">
          <p className="text-xs text-muted-foreground">Provider 注册</p>
          <p className="text-sm">
            {tool?.provider_registered ? (
              <span className="inline-flex items-center gap-1 text-green-600">
                <span className="h-2 w-2 rounded-full bg-green-500" /> 已注册
              </span>
            ) : (
              <span className="inline-flex items-center gap-1 text-gray-400">
                <span className="h-2 w-2 rounded-full bg-gray-400" /> 未注册
              </span>
            )}
          </p>
        </div>
        <div className="rounded-lg bg-muted p-3">
          <p className="text-xs text-muted-foreground">健康状态</p>
          <p className="text-sm">
            <span className={`inline-flex items-center gap-1 ${healthy ? 'text-green-600' : 'text-muted-foreground'}`}>
              {healthy ? <CheckCircle className="h-3.5 w-3.5" /> : <AlertCircle className="h-3.5 w-3.5" />}
              {healthy ? '可用' : (tool?.problem ? TOOL_STATUS_LABEL[tool.problem] || tool.problem : '不可用')}
            </span>
          </p>
        </div>
        {infoRows.map(row => (
          <div key={row.label} className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">{row.label}</p>
            <p className="font-mono text-sm truncate">{row.value || '-'}</p>
          </div>
        ))}
      </div>
    </div>
  )
}

export function Settings() {
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  const { data: config } = useQuery({ queryKey: ['config'], queryFn: api.getConfig })
  const { data: status } = useQuery({ queryKey: ['status'], queryFn: api.getStatus })
  const { data: creds } = useQuery({ queryKey: ['credentials'], queryFn: api.getCredentials })

  // 凭据配置状态
  const [tokenInput, setTokenInput] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [submitResult, setSubmitResult] = useState<{ ok: boolean; msg: string } | null>(null)

  const handleConfigureToken = async () => {
    if (!tokenInput.trim()) return
    setSubmitting(true)
    setSubmitResult(null)
    try {
      const res = await api.putCredentials(tokenInput.trim())
      if (res.error) {
        setSubmitResult({ ok: false, msg: res.error })
      } else {
        setSubmitResult({ ok: true, msg: '凭据已配置，到期: ' + (res.expires_at || '-') })
        setTokenInput('')
        queryClient.invalidateQueries({ queryKey: ['credentials'] })
        queryClient.invalidateQueries({ queryKey: ['status'] })
      }
    } catch (e: unknown) {
      setSubmitResult({ ok: false, msg: e instanceof Error ? e.message : '配置失败' })
    } finally {
      setSubmitting(false)
    }
  }

  const handleClearCredentials = async () => {
    setSubmitting(true)
    setSubmitResult(null)
    try {
      await api.deleteCredentials()
      setSubmitResult({ ok: true, msg: '凭据已清除' })
      queryClient.invalidateQueries({ queryKey: ['credentials'] })
      queryClient.invalidateQueries({ queryKey: ['status'] })
    } catch (e: unknown) {
      setSubmitResult({ ok: false, msg: e instanceof Error ? e.message : '清除失败' })
    } finally {
      setSubmitting(false)
    }
  }

  if (!config) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="animate-pulse text-muted-foreground">加载中...</div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div>
        <h2 className="text-2xl font-bold">设置</h2>
        <p className="text-muted-foreground">Agent 运行时配置</p>
      </div>

      {/* Agent Info */}
      <div className="rounded-xl border bg-card p-4">
        <h3 className="font-medium mb-3 flex items-center gap-2">
          <Info className="h-4 w-4 text-primary" /> Agent 信息
        </h3>
        <div className="grid gap-3 sm:grid-cols-2">
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">Agent ID</p>
            <p className="font-mono text-sm">{config.agent_id}</p>
          </div>
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">版本</p>
            <p className="font-mono text-sm">{status?.version || '0.0.30'}</p>
          </div>
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">运行目录</p>
            <p className="font-mono text-sm truncate">{config.runtime_home}</p>
          </div>
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">家目录</p>
            <p className="font-mono text-sm truncate">{config.home}</p>
          </div>
        </div>
      </div>

      {/* Platform Credentials */}
      <div className="rounded-xl border bg-card p-4">
        <h3 className="font-medium mb-3 flex items-center gap-2">
          <Shield className="h-4 w-4 text-primary" /> 平台凭据
        </h3>

        {/* 当前状态 */}
        {creds?.configured ? (
          <div className="space-y-3">
            <div className="grid gap-3 sm:grid-cols-2">
              <div className="rounded-lg bg-muted p-3">
                <p className="text-xs text-muted-foreground">状态</p>
                <p className="text-sm text-green-600 flex items-center gap-1">
                  <CheckCircle className="h-3.5 w-3.5" /> 已配置
                </p>
              </div>
              <div className="rounded-lg bg-muted p-3">
                <p className="text-xs text-muted-foreground">Agent ID</p>
                <p className="font-mono text-sm">{creds.agent_id || '-'}</p>
              </div>
              <div className="rounded-lg bg-muted p-3">
                <p className="text-xs text-muted-foreground">密钥</p>
                <p className="font-mono text-sm">{creds.token_masked || '-'}</p>
              </div>
              <div className="rounded-lg bg-muted p-3">
                <p className="text-xs text-muted-foreground">平台地址</p>
                <p className="font-mono text-sm truncate">{creds.platform_url || '-'}</p>
              </div>
              {creds.configured_at && (
                <div className="rounded-lg bg-muted p-3">
                  <p className="text-xs text-muted-foreground">配置时间</p>
                  <p className="font-mono text-sm">{creds.configured_at}</p>
                </div>
              )}
            </div>
            <button
              onClick={handleClearCredentials}
              disabled={submitting}
              className="inline-flex items-center gap-1.5 rounded-lg border border-red-200 px-3 py-1.5 text-sm text-red-600 hover:bg-red-50 disabled:opacity-50"
            >
              <Trash2 className="h-3.5 w-3.5" />
              清除凭据
            </button>
          </div>
        ) : (
          <div className="space-y-3">
            <div className="rounded-lg bg-muted p-3">
              <p className="text-sm text-muted-foreground">
                未配置平台凭据 — 仅本地模式可用。配置密钥后可解锁平台协同与接单模式。
              </p>
            </div>
            <div className="flex gap-2">
              <input
                type="text"
                value={tokenInput}
                onChange={e => setTokenInput(e.target.value)}
                placeholder="粘贴密钥，如 your-platform-token..."
                className="flex-1 rounded-lg border bg-background px-3 py-2 text-sm font-mono placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
                onKeyDown={e => e.key === 'Enter' && handleConfigureToken()}
              />
              <button
                onClick={handleConfigureToken}
                disabled={submitting || !tokenInput.trim()}
                className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
              >
                {submitting ? '验证中...' : '配置'}
              </button>
            </div>
            <p className="text-xs text-muted-foreground">
              在平台「数字员工」详情页或「密钥管理」页面生成密钥，复制后粘贴到此处。
              注册账号: <a href="https://openchiip.com/register" target="_blank" className="text-primary hover:underline">openchiip.com/register</a>
            </p>
          </div>
        )}

        {/* 已配置时也显示更换输入框 */}
        {creds?.configured && (
          <div className="mt-3 pt-3 border-t">
            <p className="text-xs text-muted-foreground mb-2">更换密钥:</p>
            <div className="flex gap-2">
              <input
                type="text"
                value={tokenInput}
                onChange={e => setTokenInput(e.target.value)}
                placeholder="粘贴新密钥..."
                className="flex-1 rounded-lg border bg-background px-3 py-2 text-sm font-mono placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
                onKeyDown={e => e.key === 'Enter' && handleConfigureToken()}
              />
              <button
                onClick={handleConfigureToken}
                disabled={submitting || !tokenInput.trim()}
                className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
              >
                {submitting ? '验证中...' : '更换'}
              </button>
            </div>
          </div>
        )}

        {/* 操作结果反馈 */}
        {submitResult && (
          <div className={`mt-3 flex items-center gap-2 rounded-lg p-3 text-sm ${
            submitResult.ok ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
          }`}>
            {submitResult.ok ? <CheckCircle className="h-4 w-4" /> : <AlertCircle className="h-4 w-4" />}
            {submitResult.msg}
          </div>
        )}
      </div>

      {/* LLM Config */}
      <div className="rounded-xl border bg-card p-4">
        <h3 className="font-medium mb-3 flex items-center gap-2">
          <Key className="h-4 w-4 text-primary" /> LLM 配置
        </h3>
        <div className="grid gap-3 sm:grid-cols-2">
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">提供商</p>
            <p className="font-mono text-sm">{config?.llm_configured ? '已配置' : '未配置'}</p>
          </div>
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">主模型</p>
            <p className="font-mono text-sm">{config?.model_name || '-'}</p>
          </div>
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">快速模型</p>
            <p className="font-mono text-sm">{config?.fast_model_name || '-'}</p>
          </div>
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">LLM 状态</p>
            <p className="text-sm">
              <span className={`inline-flex items-center gap-1 ${config?.llm_configured ? 'text-green-600' : 'text-red-500'}`}>
                <span className={`h-2 w-2 rounded-full ${config?.llm_configured ? 'bg-green-500' : 'bg-red-500'}`} />
                {config?.llm_configured ? '已配置' : '未配置'}
              </span>
            </p>
          </div>
        </div>
        <button
          onClick={() => navigate('/llm')}
          className="mt-3 inline-flex items-center gap-1.5 rounded-lg bg-primary px-3 py-1.5 text-sm text-primary-foreground hover:bg-primary/90"
        >
          <ArrowRight className="h-3.5 w-3.5" />
          前往配置
        </button>
      </div>

      {/* Server Config */}
      <div className="rounded-xl border bg-card p-4">
        <h3 className="font-medium mb-3 flex items-center gap-2">
          <Server className="h-4 w-4 text-primary" /> 服务器配置
        </h3>
        <div className="grid gap-3 sm:grid-cols-2">
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">HTTP 端口</p>
            <p className="font-mono text-sm">{config.port}</p>
          </div>
          <div className="rounded-lg bg-muted p-3">
            <p className="text-xs text-muted-foreground">API 文档</p>
            <a href="/docs" target="_blank" className="text-sm text-primary hover:underline">
              /docs (Swagger UI)
            </a>
          </div>
        </div>
      </div>

      {/* CLI Agent 子 Agent 工具（与统一工具系统联动） */}
      <AgentToolCard
        title="Codex 子 Agent"
        toolKey="codex"
        infoRows={[
          { label: '模型', value: config.codex?.model || '-' },
          { label: 'CLI 路径', value: config.codex?.command || '-' },
        ]}
      />

      <AgentToolCard
        title="Qoder 子 Agent"
        toolKey="qoder-cli"
        infoRows={[
          { label: 'CLI 路径', value: config.qoder?.command || '-' },
          { label: '调用模式', value: 'qodercli -p <prompt>' },
        ]}
      />

      <AgentToolCard
        title="Claude Code 子 Agent"
        toolKey="claude-code"
        infoRows={[
          { label: '模型', value: (config as { claude_code?: { model?: string } }).claude_code?.model || '-' },
          { label: 'CLI 路径', value: (config as { claude_code?: { command?: string } }).claude_code?.command || '-' },
          { label: '超时', value: ((config as { claude_code?: { timeout?: number } }).claude_code?.timeout ?? '-') + 's' },
        ]}
      />

      {/* Edit config hint */}
      <div className="rounded-xl border border-dashed bg-card p-4">
        <p className="text-sm text-muted-foreground">
          <SettingsIcon className="mr-1 inline h-4 w-4" />
          编辑配置文件: <code className="rounded bg-muted px-1.5 py-0.5 text-xs font-mono">~/.openchiip-harness/config.yaml</code>
          <br />
          或运行 <code className="rounded bg-muted px-1.5 py-0.5 text-xs font-mono">openchiip-harness init --force</code> 重新配置
        </p>
      </div>
    </div>
  )
}
